import{z as B,x as A,o as s,c as d,q as l,j as i,D as r,d as E,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"投递语义","description":"","frontmatter":{"title":"投递语义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/delivery-semantics.md","filePath":"cs/delivery-semantics.md","lastUpdated":1791413859000}'),p={name:"cs/delivery-semantics.md"};function c(D,a,m,k,f,h){const t=A("Mermaid");return s(),d("div",null,[a[2]||(a[2]=l('<h1 id="投递语义" tabindex="-1">投递语义 <a class="header-anchor" href="#投递语义" aria-label="Permalink to &quot;投递语义&quot;">​</a></h1><div class="epigraph"><p>消息队列保证的是 broker 与消费者之间的投递次数，不是业务效果。至少一次投递加非幂等处理，效果是至少两次。</p><footer>—— 据 ISO/OSI 与分布式教材中的可靠广播分类；Kreps 等对日志投递的实践整理</footer></div><p>上一课<a href="/cs/rpc-semantics">RPC</a>谈过程执行次数。缺口是<strong>异步消息</strong>：生产者、队列、消费者三方，ack 点不同，词还是至少/至多/恰好，指称对象却换成「消息从队列消失几次、被处理几次」。本课钉投递，不重写桩。后课幂等键把效果钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>至少一次投递：消费者可能收到重复（崩溃在 ack 前）。至多一次：可能丢（ack 先于处理）。恰好一次投递：broker 与消费者协议让每条消息对消费者的<strong>可见处理</strong>一次——通常用事务消费或幂等生产者 id + 去重表，底层仍常是至少一次运输。</p><p><span class="marginnote">术语翻译：这三种语义都在回答「同一条消息会被处理几次」。至少一次＝保证送到、可能送两遍；至多一次＝保证不重复、可能弄丢；恰好一次＝不多不少一次——但工程里它几乎总是「至少一次运输＋你自己负责去重」的化名，不是运输层凭空变出来的魔法。</span></p><p>缺口：把 Kafka <code>acks=all</code> 当恰好一次业务。那是生产者到日志的持久，不是下游两次副作用。EOS（ exactly-once semantics）是特定系统里「读-处理-写」事务的品牌，规格要读论文与文档的限定范围，本课只警告品牌 ≠ 全局恰好一次。</p><p><span class="marginnote">可靠广播、FIFO 广播、因果广播是另一轴（排序），不要和次数轴混成一个词。Birman 的 Isis 谈排序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 ack 点：处理前 ack ⇒ 可丢；处理后 ack ⇒ 可重复。恰好一次效果：至少一次投递 + 幂等处理，或两者包进同一事务（消费位移与副作用同提交）。</p>',10)),(s(),i(n,null,{default:r(()=>[o(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E7%94%9F%E4%BA%A7%E8%80%85%22%5D%20--%3E%20Q%5B%22%E9%98%9F%E5%88%97%20%2F%20%E6%97%A5%E5%BF%97%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%22%5D%0A%20%20C%20--%3E%20ACK%5B%22ack%20%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20ACK%20--%3E%20DUP%7B%22ack%20%E4%B8%8E%E5%89%AF%E4%BD%9C%E7%94%A8%E6%AC%A1%E5%BA%8F%22%7D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"死信、重试次数上限是工程，把无限至少一次切成有界。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("重复来源：生产者重试未收到 broker ack（要生产者幂等键）、消费者重平衡时位移回退、网络重传。丢失来源：位移先提交、broker 未刷盘就 ack、TTL 丢弃。与"),e("a",{href:"/cs/replicated-state-machine"},"RSM"),E("：日志提交是多数派持久，投给消费者仍是另一通道。")],-1)),a[6]||(a[6]=e("p",null,"重复和丢失各有固定的来源清单，可以按「消息在哪一步出事」对号入座：",-1)),(s(),i(n,null,{default:r(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%B6%88%E6%81%AF%E5%9C%A8%E5%93%AA%E4%B8%80%E6%AD%A5%E5%87%BA%E4%BA%86%E4%BA%8B%22%5D%20--%3E%20DUP%5B%22%E8%A1%A8%E7%8E%B0%E4%B8%BA%E9%87%8D%E5%A4%8D%22%5D%0A%20%20Q%20--%3E%20LOSS%5B%22%E8%A1%A8%E7%8E%B0%E4%B8%BA%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20DUP%20--%3E%20D1%5B%22%E7%94%9F%E4%BA%A7%E8%80%85%E9%87%8D%E8%AF%95%EF%BC%8C%E5%85%B6%E5%AE%9E%E9%A6%96%E6%AC%A1%E5%B7%B2%E5%85%A5%E9%98%9F%22%5D%0A%20%20DUP%20--%3E%20D2%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%E9%87%8D%E5%B9%B3%E8%A1%A1%EF%BC%9A%E4%BD%8D%E7%A7%BB%E5%9B%9E%E9%80%80%E9%87%8D%E6%8A%95%22%5D%0A%20%20DUP%20--%3E%20D3%5B%22%E7%BD%91%E7%BB%9C%E9%87%8D%E4%BC%A0%22%5D%0A%20%20LOSS%20--%3E%20L1%5B%22%E5%A4%84%E7%90%86%E5%89%8D%E5%85%88%E6%8F%90%E4%BA%A4%E4%BD%8D%E7%A7%BB%E5%90%8E%E5%B4%A9%E6%BA%83%22%5D%0A%20%20LOSS%20--%3E%20L2%5B%22broker%20%E6%9C%AA%E5%88%B7%E7%9B%98%E5%B0%B1%20ack%20%E5%90%8E%E5%AE%95%E6%9C%BA%22%5D%0A%20%20LOSS%20--%3E%20L3%5B%22TTL%20%E5%88%B0%E6%9C%9F%E8%A2%AB%E4%B8%A2%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">直觉类比：至少一次投递像「送到为止」的快递员——你不在家就反复来敲门，同一件包裹可能被敲两次门；至多一次像「路过放门口就走」，可能被别人顺走。想要「只办一次事」的效果，得在门口装一本签收登记（幂等键 / 去重表），来两次也只登记一次。</span></p><p><span class="marginnote">常见误区：初学者容易把 Kafka 的 <code>acks=all</code> 当成「业务恰好一次」。它只保证这条消息写进了日志不丢（生产者侧的持久性），下游消费、处理、提交位移的每一步仍可能重复或失败。看到「恰好一次」的广告词，先问主语：一次的是投递、可见处理，还是业务副作用？</span></p><p>本课不写 Kafka 事务协议全文（后课日志课抓副本与位移）。也不把邮件 SMTP 的重试当队列定理。</p><p>与 RPC 对照：同步 RPC 的重试对应生产者重试；服务端 xid 表对应消费者去重表。换了拓扑，代数一样。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Saga 补偿流。不把 MQTT QoS 0/1/2 当新理论，只点名它们是同一分类。后课默认：队列广告词先翻译成 ack 点；效果一次靠幂等或事务。下一课专讲幂等键。</p><p>次数保证有主语。主语是 broker 还是业务表，答案不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>投递次数 ≠ 业务效果次数。</li><li>处理后 ack 可重复；处理前 ack 可丢失。</li><li>恰好一次效果 = 至少一次运输 + 幂等或事务去重。</li><li>出处：可靠通信分类；日志系统实践（Kreps 等）。</li></ul>',9))])}const C=B(p,[["render",c]]);export{u as __pageData,C as default};
